update survey_assign_org a,survey_risk_case_info s set a.survey_org_id = #{surveyOrgId,jdbcType=BIGINT},a.survey_org_name = #{surveyOrgName,jdbcType=VARCHAR}
where a.delete_flag = 0 and a.survey_info_id = s.id and s.entrust_report_end_date is null and a.survey_org_id = #{oldSurveyOrgId,jdbcType=BIGINT};

update survey_investigator_case a,survey_risk_case_info s set a.survey_org_id = #{surveyOrgId,jdbcType=BIGINT},a.survey_org_name = #{surveyOrgName,jdbcType=VARCHAR}
where a.delete_flag = 0 and a.survey_info_id = s.id and s.entrust_report_end_date is null and a.survey_org_id = #{oldSurveyOrgId,jdbcType=BIGINT};

update survey_case_direction a,survey_risk_case_info s set a.survey_org_id = #{surveyOrgId,jdbcType=BIGINT},a.survey_org_name = #{surveyOrgName,jdbcType=VARCHAR}
