mapper.select:
select c.survey_case_no as surveyCaseNo, c.id as surveyId, i.id as surveyInfoId, i.entrust_org_id as entrustOrgId, i.entrust_org_name as entrustOrgName, c.survey_person as surveyPerson, c.survery_person_tel as surveryPersonTel, i.survey_state as surveyState, i.survey_state_name as surveyStateName, c.entrust_time as entrustTime, o.id as surveyAssignOrgId, o.survey_org_id as surveyOrgId, o.survey_org_name as surveyOrgName, o.org_survey_state as orgSurveyState, o.org_survey_state_name as orgSurveyStateName, o.create_time as orgAssignDate, o.report_date as orgReportDate, o.org_end_time as orgEndTime, o.return_state as vetoNum, i.end_time as endTime from survey_assign_org o left join survey_risk_case_info i on o.survey_info_id = i.id left join survey_risk_case c on o.survey_id = c.id where o.delete_flag = 0 and o.survey_org_id = #{surveyOrgId,jdbcType=BIGINT}
and ((o.org_survey_state = 4 and DATE_FORMAT(o.report_date,'%Y-%m-%d') > DATE_FORMAT(o.org_end_time,'%Y-%m-%d')) or (o.org_survey_state != 4 and DATE_FORMAT(SYSDATE(),'%Y-%m-%d') > DATE_FORMAT(o.org_end_time,'%Y-%m-%d')))
and o.return_state > 0
group by o.survey_org_id,o.survey_info_id order by o.id asc
limit #{pageIndex}, #{pageSize}

select from survey_assign_org a
a.delete_flag = 0
and a.survey_info_id=#{surveyInfoId}

select A.surveyNo as surveyNo, A.id as assignCaseId, A.survey_org_id as surveyOrgId, A.survey_id as surveyId, A.survey_info_id as surveyInfoId, A.surveyPerson as surveyPerson, A.entrustOrgName as entrustOrgName from ( select a.id, a.survey_org_id, a.survey_id, a.survey_info_id,s1.entrust_org_name as entrustOrgName, a.survey_investigator_case_id, s1.survey_no as surveyNo, s2.survey_person as surveyPerson from survey_assign_org a left join survey_investigator_case i on a.id = i.survey_assorg_case_id and i.delete_flag = 0 left join survey_risk_case_info s1 on a.survey_info_id = s1.id left join survey_risk_case s2 on a.survey_id = s2.id left join survey_consignor n on s1.entrust_org_id = n.id where a.delete_flag = 0 and s1.delete_flag = 0
and n.org_attr = #{orgAttr,jdbcType=INTEGER}
) A group by A.survey_info_id
limit #{pageIndex}, #{pageSize}

select count(1) from ( select A.surveyNo as surveyNo, A.id as assignCaseId, A.survey_org_id as surveyOrgId, A.survey_id as surveyId, A.survey_info_id as surveyInfoId, A.surveyPerson as surveyPerson, A.entrustOrgName as entrustOrgName from ( select a.id, a.survey_org_id, a.survey_id, a.survey_info_id,s1.entrust_org_name as entrustOrgName, a.survey_investigator_case_id, s1.survey_no as surveyNo, s2.survey_person as surveyPerson from survey_assign_org a left join survey_investigator_case i on a.id = i.survey_assorg_case_id and i.delete_flag = 0 left join survey_risk_case_info s1 on a.survey_info_id = s1.id left join survey_risk_case s2 on a.survey_id = s2.id left join survey_consignor n on s1.entrust_org_id = n.id where a.delete_flag = 0 and s1.delete_flag = 0
and n.org_attr = #{orgAttr,jdbcType=INTEGER}
) A group by A.survey_info_id ) B
